head.script:
scwin.btn_create_shelf_add_355_add_485_onclick = function(e) {
    scwin.appendBtn("card_style1", edt_rack_count_add_352_add_482.getValue(), edit_shlf_count_add_354_add_484.getValue(), "네모");
};
scwin.appendBtn = function(pClass, row, col, title) {
    var width = WebSquare.wUnit.getJq("#div_shelf_draw").width(); //박스넓이
    var height = WebSquare.wUnit.getJq("#div_shelf_draw").height(); //박스높이
    var wc = width / col;
    var hr = height / row;
    var left = 0;
    var top = 0;
    for (var i = 0; i < row; i++) {
        left = 0;
        for (var j = 0; j < col; j++) {
            //버튼생성 및 설정
            var inputbox = document.createElement("input");
            inputbox.type = "button";
            inputbox.id = "btn_equip" + i + "_" + j; //버튼아이디
            inputbox.className = "w2trigger " + pClass; //버튼클래스
            inputbox.value = title + i + "_" + j; //버튼명
            inputbox.style.width = wc + "px"; //버튼넓이
            inputbox.style.height = hr + "px"; //버튼높이
            inputbox.style.left = left + "px"; //버튼 왼쪽좌표
            inputbox.style.top = top + "px"; //버튼 위쪽좌표
            //버튼에 onclick 이벤트 바인딩
            inputbox.onclick = function(e) {
                scwin.clickFunction(this.value);
            };
            //박스에 붙이기
            WebSquare.wUnit.getJq("#div_shelf_draw").append(inputbox);
            //툴팁설정
            scwin.setTooltip(inputbox.id, "나나나나" + i + "_" + j, "right");
            left += wc;
        }
        top += hr;
    }
};
scwin.clickFunction = function(param) {
    alert(param);
};
scwin.setTooltip = function(targetId, msg, position) {
    try {
        WebSquare.wUnit.getJq("#" + targetId).unbind("mouseenter mouseleave");
        WebSquare.wUnit.getJq("#" + targetId).hover(
            function() {
                var comp = WebSquare.wUnit.getObjById(this.id);
                var addStyle = "";
                if (true) {
                    var tooltipDiv = document.createElement("div");
                    tooltipDiv.setAttribute("id", "tooltipDiv");
                    tooltipDiv.setAttribute("class", "w2group tip_ov ");
                    tooltipDiv.setAttribute("style", "position:absolute; max-width:400px; top:0; left:0; z-index:5200; word-break: break-all;");
                    var tooltip = document.createElement("div");
                    tooltip.setAttribute("id", "tooltip");
                    tooltip.setAttribute("class", "w2textbox");
                    tooltip.innerHTML = msg;
                    tooltipDiv.appendChild(tooltip);
                    document.body.appendChild(tooltipDiv);
                } else {
                    var tooltip = WebSquare.wUnit.getDomById($p.id + "tooltip");
                    tooltip.innerHTML = msg;
                }
                var setTop = 0;
                var setLeft = 0;
                var type = "";
                var t1 = WebSquare.wUnit.getJq("#" + this.id).offset().top;
                var t2 = WebSquare.wUnit.getJq("#tooltipDiv").outerHeight();
                var l1 = WebSquare.wUnit.getJq("#" + this.id).offset().left + WebSquare.wUnit.getJq("#" + this.id).outerWidth() / 2;
                var l2 = WebSquare.wUnit.getJq("#tooltipDiv").outerWidth() / 2;
                var l3 = WebSquare.wUnit.getJq("#" + this.id).offset().top + WebSquare.wUnit.getJq("#" + this.id).outerWidth() / 2;
                var l4 = WebSquare.wUnit.getJq("#tooltipDiv").outerHeight() / 2;
                var r1 = WebSquare.wUnit.getJq("body").outerWidth() - WebSquare.wUnit.getJq("#" + this.id).offset().left - WebSquare.wUnit.getJq("#" + this.id).outerWidth();
                var r2 = WebSquare.wUnit.getJq("#tooltipDiv").outerWidth();
                var r3 = WebSquare.wUnit.getJq("#" + this.id).offset().top + WebSquare.wUnit.getJq("#" + this.id).outerWidth() / 2;
                var r4 = WebSquare.wUnit.getJq("#tooltipDiv").outerHeight() / 2;
                if (t1 < t2) {
                    if (l1 < l2 && l3 > l4) {
                        type = "right";
                    } else if (l1 < l2 && r1 < r2 && r3 > r4) {
                        type = "left";
                    } else {
                        type = "bottom";
                    }
                } else {
                    if (l1 < l2 && l3 > l4) {
                        type = "right";
                    } else if (l1 < l2 && r1 < r2 && r3 > r4) {
                        type = "left";
                    } else {
                        type = "top";
                    }
                }
                if (typeof position != "undefined") {
                    switch (position.toLowerCase()) {
                        case "left":
                            type = "left";
                            break;
                        case "right":
                            type = "right";
                            break;
                        case "top":
                            type = "top";
                            break;
                        case "bottom":
                            type = "bottom";
                            break;
                    }
                }
                if (type == "left" || type == "right") {
                    setTop = WebSquare.wUnit.getJq("#" + this.id).offset().top - WebSquare.wUnit.getJq("#tooltipDiv").outerHeight() / 2 + WebSquare.wUnit.getJq("#" + this.id).outerHeight() / 2;
                    if (type == "left") {
                        WebSquare.wUnit.getJq("#tooltipDiv").addClass("left mr20");
                        setLeft = WebSquare.wUnit.getJq("#" + this.id).offset().left - WebSquare.wUnit.getJq("#tooltipDiv").outerWidth() - 20;
                    } else {
                        WebSquare.wUnit.getJq("#tooltipDiv").addClass("right ml20");
                        setLeft = WebSquare.wUnit.getJq("#" + this.id).offset().left + WebSquare.wUnit.getJq("#" + this.id).outerWidth() - 20;
                    }
                } else if (type == "bottom" || type == "top") {
                    setLeft = WebSquare.wUnit.getJq("#" + this.id).offset().left - WebSquare.wUnit.getJq("#tooltipDiv").outerWidth() / 2 + WebSquare.wUnit.getJq("#" + this.id).outerWidth() / 2 - 10;
                    if (type == "top") {
                        WebSquare.wUnit.getJq("#tooltipDiv").addClass("top mb20");
                        setTop = WebSquare.wUnit.getJq("#" + this.id).offset().top - WebSquare.wUnit.getJq("#tooltipDiv").outerHeight() - 20;
                    } else {
                        WebSquare.wUnit.getJq("#tooltipDiv").addClass("bottom mt20");
                        setTop = WebSquare.wUnit.getJq("#" + this.id).offset().top + WebSquare.wUnit.getJq("#" + this.id).outerHeight();
                    }
                } else {
                    setLeft = WebSquare.wUnit.getJq("#" + this.id).offset().left - WebSquare.wUnit.getJq("#tooltipDiv").outerWidth() / 2 + WebSquare.wUnit.getJq("#" + this.id).outerWidth() / 2 - 10;
                    setTop = WebSquare.wUnit.getJq("#" + this.id).offset().top + WebSquare.wUnit.getJq("#" + this.id).outerHeight();
                }
                WebSquare.wUnit.getJq("#tooltipDiv").css({
                    "top": setTop,
                    "left": setLeft
                });
            },
            function() {
                WebSquare.wUnit.getJq("#tooltip").remove();
                WebSquare.wUnit.getJq("#tooltipDiv").remove();
            }
        );
    } catch (e) {}
};
scwin.bindDragDrop = function(grid, dragAndDropCallback) {
    grid.bind("onmousedown", function(e) {
        var it = this.event.getTargetIterator(e);
        while (it.next()) {
            if (it.match(null, null, "td")) {
                var tdElem = it.getElement();
                var value = [];
                var rowIndex = this.rowIndex + parseInt(parseInt(tdElem.getAttribute("tdIndex")) / (this.oneRowDataLength + this.defaultColCnt));
                var colId = tdElem.getAttribute("col_id");
                value.push(colId);
                var displayValue = [];
                for (var i = 0; i < value.length; i++) {
                    displayValue.push(this.getCellDisplayData(rowIndex, value[i].wq_trim()));
                }
                displayValue = displayValue.join(",");
                var _this = this;
                WebSquare.dragdrop.gDragManager.activate(e, tdElem, {
                    id: this.id + "_drag",
                    component: _this,
                    className: "w2grid_drag",
                    contents: displayValue,
                    delay: 15,
                    applyMousePosition: true,
                    onDrop: function(drag, drop, x, y, dx, dy, e) {
                        var targetTrigger = null;
                        var targetGrid = null;
                        var it2 = null;
                        if (this.isMobile) {
                            it2 = new WebSquare.targetIterator(document.elementFromPoint(e.changedTouches[0].clientX, e.changedTouches[0].clientY));
                            e.preventDefault();
                        } else {
                            it2 = _this.event.getTargetIterator(e);
                        }
                        while (it2.next()) {
                            debugger;
                            if (it2.match("w2trigger")) {
                                targetTrigger = it2.getElement().id;
                            }
                        }
                        targetTrigger = WebSquare.wUnit.getObjById(targetTrigger);
                        if (typeof targetGrid === "object") {
                            if (scwin.isFunction(dragAndDropCallback)) {
                                dragAndDropCallback(targetTrigger, rowIndex, colId);
                            } else {
                                eval(dragAndDropCallback + "(targetTrigger,rowIndex,colId)");
                            }
                        }
                        return;
                    }
                });
            }
        }
    });
};
scwin.dragDropCallBack = function(triggerObj, rowIdx, colID) {
    console.log("triggerID: " + triggerObj.id);
    console.log("rowIdx: " + rowIdx);
    console.log("colID: " + colID);
    var currow = dataList2.insertRow();
    dataList2.setCellData(currow, "col1", triggerObj.value);
    dataList2.setCellData(currow, "col2", rowIdx);
    dataList2.setCellData(currow, "col3", colID);
};
scwin.isFunction = function(functionToCheck) {
    var getType = {};
    return functionToCheck && getType.toString.call(functionToCheck) === '[object Function]';
};
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. 샘플파일을 실행 후 그리드의 name4항목의 이미지 활성화여부를 확인한다.
    //1. Execute sample file and check whether image of name4 item of grid is activated.
    WebSquare.wUnit.addCommand("pause", "1000");
    //Verify step 1. name4항목의 이미지가 비활성화(disabled)되는 효과가 확인된다.(이전엔진버전은 활성화되어짐)
    //1. The effect of disabling the image of the name4 item is confirmed (previous engine version is enabled).
    //WebSquare.wUnit.addCommand("assert", "document.getElementsByClassName('w2grid_textImage_image w2grid_textImage_disabled').length > 0", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.w2grid_textImage_image.w2grid_textImage_disabled').length > 0", "true");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    // 바인딩 DragDrop
    //1. 방식1 :  함수로 직접 호출
    /*scwin.bindDragDrop( gridView0, function(triggerObj, rowIdx, colID){
