    	dataList2.setCellData(currow, "col2", rowIdx);
    	dataList2.setCellData(currow, "col3", colID);
    });*/
    // 2. 방식2 : CallBack 처리
    scwin.bindDragDrop(gridView0, "scwin.dragDropCallBack");
    //방식2의 콜백
    //Function 
    //Created by: Quan.Nguyen
